// Conformance harness consuming the shared libphext 0.6.1 range fixtures in
// tests/fixtures/ranges/ (see FIXTURES-RANGES.md in the ports program workspace;
// the set was generated by calling libphext-rs 0.6.1 itself, and extends the
// 0.6 chain fixtures). Mirrors libphext-rs tests/range_fixtures.rs.
//
// For every case: parse input.phext with parse_chains, take chain 0, and run
// every recorded op in expected.tsv against the v0.6.1 addressing API
// (parse_point_address / parse_range_address / Chain::resolve_point /
// Chain::resolve_range / Chain::fetch_point / Chain::fetch_range), comparing
// canonical forms, resolutions, resolved flags, and fetched bytes exactly.
#include "../phext.h"

#include <cstdio>
#include <fstream>
#include <sstream>
#include <string>
#include <tuple>
#include <utility>
#include <vector>

static int checks = 0;
static int failures = 0;
static int total_ops = 0;
static std::string current_case;

static std::string escape_bytes(const std::string& s) {
   std::string out;
   char buf[8];
   for (char raw : s) {
      const unsigned char b = static_cast<unsigned char>(raw);
      if (b >= 0x20 && b < 0x7F) out.push_back(raw);
      else { std::snprintf(buf, sizeof(buf), "\\x%02x", b); out += buf; }
   }
   return out;
}
static void fail(const std::string& what) {
   failures += 1;
   std::printf("  FAIL [%s] %s\n", current_case.c_str(), what.c_str());
}
static void check_eq_str(const std::string& a, const std::string& e, const std::string& what) {
   checks += 1;
   if (a != e) fail(what + ": actual \"" + escape_bytes(a.substr(0, 80)) + "\" (" + std::to_string(a.size()) +
                    " bytes) expected \"" + escape_bytes(e.substr(0, 80)) + "\" (" + std::to_string(e.size()) + " bytes)");
}
static void check_eq_size(std::size_t a, std::size_t e, const std::string& what) {
   checks += 1;
   if (a != e) fail(what + ": actual " + std::to_string(a) + " expected " + std::to_string(e));
}
static void check_eq_bool(bool a, bool e, const std::string& what) {
   checks += 1;
   if (a != e) fail(what + std::string(": actual ") + (a ? "true" : "false") + " expected " + (e ? "true" : "false"));
}

static std::string read_binary(const std::string& path) {
   std::ifstream in(path, std::ios::binary);
   std::stringstream ss;
   ss << in.rdbuf();
   return ss.str();
}
static std::vector<std::string> split_tab(const std::string& line) {
   std::vector<std::string> out;
   std::size_t start = 0;
   for (std::size_t i = 0; i <= line.size(); ++i) {
      if (i == line.size() || line[i] == '\t') { out.push_back(line.substr(start, i - start)); start = i + 1; }
   }
   return out;
}
static std::string field(const std::vector<std::string>& fields, const std::string& key) {
   for (const std::string& f : fields) {
      const std::size_t eq = f.find('=');
      if (eq != std::string::npos && f.substr(0, eq) == key) return f.substr(eq + 1);
   }
   return "";
}

static void run_case(const std::string& root, const std::string& case_name) {
   current_case = case_name;
   const std::string dir = root + "/" + case_name;
   const std::string tsv = read_binary(dir + "/expected.tsv");
   const std::string input = read_binary(dir + "/input.phext");

   const auto chains = phext::parse_chains(input);
   checks += 1;
   if (chains.empty()) { fail("parse_chains returned no chains"); return; }
   const phext::Chain& chain = chains[0];

   int case_ops = 0;
   std::stringstream lines(tsv);
   std::string line;
   while (std::getline(lines, line)) {
      if (!line.empty() && line.back() == '\r') line.pop_back();
      if (line.empty()) continue;
      const auto f = split_tab(line);
      if (f[0] == "input_bytes") {
         check_eq_size(input.size(), static_cast<std::size_t>(std::stoull(f[1])), "input_bytes");
         continue;
      }
      if (f[0] != "op") continue;
      case_ops += 1;
      total_ops += 1;
      const std::string& kind = f[1];
      const std::string& addr = f[2];
      const std::string at = "op " + std::to_string(case_ops) + " (" + kind + " " + addr + ")";
      if (kind == "parse_point") {
         const bool error = field(f, "error") == "true";
         const auto parsed = phext::parse_point_address(addr);
         check_eq_bool(parsed.has_value(), !error, at + ": parse outcome");
         if (parsed.has_value() && !error) check_eq_str(parsed->to_string(), field(f, "canonical"), at + ": canonical");
      } else if (kind == "parse_range") {
         const bool error = field(f, "error") == "true";
         const auto parsed = phext::parse_range_address(addr);
         check_eq_bool(parsed.has_value(), !error, at + ": parse outcome");
         if (parsed.has_value() && !error) check_eq_str(parsed->to_string(), field(f, "canonical"), at + ": canonical");
      } else if (kind == "resolve_point") {
         const bool error = field(f, "error") == "true";
         const auto point = phext::parse_point_address(addr);
         checks += 1;
         if (!point.has_value()) { fail(at + ": resolve op input must parse"); continue; }
         const auto resolved = chain.resolve_point(*point);
         check_eq_bool(resolved.has_value(), !error, at + ": resolve outcome");
         if (resolved.has_value() && !error) {
            const std::string want = std::to_string(std::get<0>(*resolved)) + "|" +
                                     std::get<1>(*resolved).to_string() + "|" +
                                     std::to_string(std::get<2>(*resolved));
            check_eq_str(want, field(f, "resolve"), at + ": resolution");
         }
      } else if (kind == "fetch_point") {
         const bool resolved_flag = field(f, "resolved") == "true";
         const auto point = phext::parse_point_address(addr);
         const bool actual_resolved = point.has_value() && chain.resolve_point(*point).has_value();
         check_eq_bool(actual_resolved, resolved_flag, at + ": resolved flag");
         const std::string expected = read_binary(dir + "/" + field(f, "file"));
         check_eq_str(chain.fetch_point(addr), expected, at + ": fetch_point bytes");
      } else if (kind == "fetch_range") {
         const bool resolved_flag = field(f, "resolved") == "true";
         const auto range = phext::parse_range_address(addr);
         const bool actual_resolved = range.has_value() && chain.resolve_range(*range).has_value();
         check_eq_bool(actual_resolved, resolved_flag, at + ": resolved flag");
         const std::string expected = read_binary(dir + "/" + field(f, "file"));
         check_eq_str(chain.fetch_range(addr), expected, at + ": fetch_range bytes");
      } else {
         checks += 1;
         fail(at + ": unknown op kind " + kind);
      }
   }
   std::printf("%s %s (%d ops)\n", failures == 0 ? "PASS" : "case-done", case_name.c_str(), case_ops);
}

int main() {
   const std::string root = "tests/fixtures/ranges";
   const std::string index = read_binary(root + "/cases.tsv");
   std::stringstream lines(index);
   std::string line;
   int case_count = 0;
   bool first = true;
   while (std::getline(lines, line)) {
      if (!line.empty() && line.back() == '\r') line.pop_back();
      if (first) { first = false; continue; }
      if (line.empty()) continue;
      const std::string case_name = split_tab(line)[0];
      case_count += 1;
      run_case(root, case_name);
   }
   checks += 1; if (case_count != 6) fail("expected 6 fixture cases, got " + std::to_string(case_count));
   checks += 1; if (total_ops != 69) fail("expected 69 fixture ops, got " + std::to_string(total_ops));
   std::printf("test_range_fixtures: %d cases, %d ops, %d checks, %d failures\n", case_count, total_ops, checks, failures);
   return failures > 125 ? 125 : failures;
}
